<?php $this->assign('title', $compra->numero); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3"><?= h($compra->numero) ?></h1><span class="badge text-bg-secondary"><?= h($compra->status) ?></span></div><?php if (in_array($compra->status, ['emitida', 'recebida_parcialmente'], true)): ?><?= $this->Html->link('Receber mercadoria', ['action' => 'receber', $compra->id], ['class' => 'btn btn-primary']) ?><?php endif; ?></div><div class="card border-0 shadow-sm"><table class="table mb-0"><thead><tr><th>Item</th><th>Pedido</th><th>Recebido</th><th>Preço</th></tr></thead><tbody><?php foreach ($compra->compras_itens as $item): ?><tr><td><?= h($item->medicamento?->nome_comercial ?? $item->produto?->nome ?? '-') ?></td><td><?= h($item->quantidade) ?></td><td><?= h($item->quantidade_recebida) ?></td><td><?= h($item->preco_unitario) ?></td></tr><?php endforeach; ?></tbody></table></div>
